package com.hospisoft.dao;

import com.hospisoft.model.Auditoria;
import com.hospisoft.model.Page;

/**
 * Append-only access to table auditoria: rows are inserted and listed, never updated or deleted
 * (the database triggers reject UPDATE, DELETE and TRUNCATE). Implementations throw db-layer
 * exceptions when the database fails.
 */
public interface AuditoriaRepository {

    /** Inserts one entry; {@code id} and {@code fecha} are ignored (generated by the database). */
    void insert(Auditoria entry);

    /** Newest first ({@code fecha DESC, id DESC}). */
    Page<Auditoria> findPage(AuditoriaQuery query, int page, int pageSize);
}
